-- Packages (honeymoon / friends / family / adventure) become their own kind, like hotels / excursions / transfers.
-- STEP 1 of 2 — run this file ALONE first on an existing database, then run 20261106000200_packages.sql in a second run:
-- Postgres refuses to use a brand-new enum value in the same transaction that adds it.
-- (A fresh install already creates the enum with 'package' in it, so this is a no-op there.)
alter type public.property_kind add value if not exists 'package';


-- ==============================================================================================================
-- migration: 20261106000200_packages.sql
-- ==============================================================================================================
-- Packages as their own kind — STEP 2 of 2 (run after 20261106000100_package_kind_enum.sql).
-- Adds: commission rate for packages, the packages_owner role, the 'package' booking type, and a per-package price mode.
--
-- Package item JSON (data):  price (EGP), priceMode = 'person' (default: price x participants) | 'package' (one price for the whole package),
--                            groupSize (people the package covers; shown to guests, used as the head count when priceMode = 'package'),
--                            packageType = honeymoon | friends | family | adventure, days.

alter table public.platform_settings
  add column if not exists commission_package numeric(5,4) not null default 0.1000 check (commission_package between 0 and 1);

alter table public.bookings drop constraint if exists bookings_kind_check;
alter table public.bookings add constraint bookings_kind_check check (kind in ('hotel', 'excursion', 'transfer', 'package'));

-- roles <-> kinds
create or replace function public.partner_type_kinds(t text)
returns public.property_kind[] language sql immutable set search_path = '' as $$
  select case lower(coalesce(t, ''))
    when 'hotel'         then array['hotel']::public.property_kind[]
    when 'hotels'        then array['hotel']::public.property_kind[]
    when 'trips'         then array['excursion']::public.property_kind[]
    when 'trip'          then array['excursion']::public.property_kind[]
    when 'trip supplier' then array['excursion']::public.property_kind[]
    when 'excursion'     then array['excursion']::public.property_kind[]
    when 'excursions'    then array['excursion']::public.property_kind[]
    when 'tour'          then array['excursion']::public.property_kind[]
    when 'transfer'      then array['transfer']::public.property_kind[]
    when 'transfers'     then array['transfer']::public.property_kind[]
    when 'package'       then array['package']::public.property_kind[]
    when 'packages'      then array['package']::public.property_kind[]
    when 'honeymoon'     then array['package']::public.property_kind[]
    when 'restaurant'    then array['restaurant']::public.property_kind[]
    when 'restaurants'   then array['restaurant']::public.property_kind[]
    else '{}'::public.property_kind[]
  end
$$;

create or replace function public.console_role_kinds(p_role text)
returns public.property_kind[] language sql immutable set search_path = '' as $$
  select case p_role
    when 'hotels_owner'      then array['hotel']::public.property_kind[]
    when 'trips_owner'       then array['excursion']::public.property_kind[]
    when 'packages_owner'    then array['package']::public.property_kind[]
    when 'transfers_owner'   then array['transfer']::public.property_kind[]
    when 'restaurants_owner' then array['restaurant']::public.property_kind[]
    else null
  end
$$;

-- price check + booking creation (adds the 'package' type; excursions behave exactly as before)
create or replace function public.compute_booking_price(p jsonb, item jsonb)
returns jsonb language plpgsql stable set search_path = '' as $$
declare
  v_type       text := p->>'type';
  v_today      date := (now() at time zone 'Africa/Cairo')::date;
  v_rate       numeric;
  v_subtotal   numeric;
  v_taxes      numeric;
  v_total      numeric;
  v_deposit    numeric;
  v_nights     integer;
  v_in         date;
  v_out        date;
  v_day        date;
  v_adults     integer;
  v_children   integer;
  v_rooms      integer;
  v_list       jsonb;
  v_room       jsonb;
  v_idx        integer := -1;
  v_want       text[];
  v_base       numeric;
  v_extra_ad   numeric;
  v_extra_n    numeric;
  v_free       integer;
  v_child_pn   numeric := 0;
  v_blocked    jsonb;
begin
  if v_type not in ('hotel', 'excursion', 'transfer', 'package') then
    raise exception 'Unknown booking type' using errcode = '22023';
  end if;
  v_rate := case v_type when 'hotel' then 0.10 else 0.05 end;

  if v_type = 'hotel' then
    if coalesce(p->>'checkin', '') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(p->>'checkout', '') !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'Invalid dates' using errcode = '22023';
    end if;
    begin
      v_in := (p->>'checkin')::date;
      v_out := (p->>'checkout')::date;
    exception when others then
      raise exception 'Invalid dates' using errcode = '22023';
    end;
    if v_in < v_today then raise exception 'Check-in date is in the past' using errcode = '22023'; end if;
    if v_out <= v_in then raise exception 'Check-out must be after check-in' using errcode = '22023'; end if;
    v_nights := greatest(1, v_out - v_in);
    if v_nights > 60 then raise exception 'Stay too long' using errcode = '22023'; end if;

    v_adults   := public._req_int(p->>'adults', 1, 10, 'adults');
    v_children := public._req_int(coalesce(p->>'children', '0'), 0, 6, 'children');
    v_rooms    := public._req_int(p->>'rooms', 1, 5, 'rooms');

    v_list := case when jsonb_typeof(item->'rooms') = 'array' then item->'rooms' else '[]'::jsonb end;
    if jsonb_typeof(p->'roomIndex') = 'number' and (p->>'roomIndex') ~ '^[0-9]+$' then
      v_idx := (p->>'roomIndex')::integer;
    else
      v_want := case when jsonb_typeof(p->'roomType') = 'object'
                     then array(select value from jsonb_each_text(p->'roomType'))
                     else array[p->>'roomType'] end;
      select (t.ord - 1)::integer into v_idx
        from jsonb_array_elements(v_list) with ordinality as t(r, ord)
       where exists (
               select 1 from jsonb_each_text(case when jsonb_typeof(t.r->'type') = 'object' then t.r->'type' else '{}'::jsonb end) e
                where e.value = any (v_want)
             )
          or (jsonb_typeof(t.r->'type') = 'string' and (t.r->>'type') = any (v_want))
       order by t.ord
       limit 1;
      v_idx := coalesce(v_idx, -1);
    end if;
    v_room := case when v_idx >= 0 then v_list->v_idx end;
    if v_room is null or jsonb_typeof(v_room->'price') <> 'number' then
      raise exception 'Room not found' using errcode = '22023';
    end if;

    v_blocked := case when jsonb_typeof(item->'unavailableDates') = 'array' then item->'unavailableDates' else '[]'::jsonb end;
    for i in 0 .. v_nights - 1 loop
      v_day := v_in + i;
      if v_blocked ? to_char(v_day, 'YYYY-MM-DD') then
        raise exception 'Selected dates are not available' using errcode = 'P0001', detail = 'unavailable';
      end if;
    end loop;

    v_base     := coalesce(nullif(v_room->>'baseOccupancy', '')::numeric, 0);
    if v_base = 0 then v_base := 2; end if;
    v_extra_ad := coalesce(nullif(v_room->>'extraAdultFee', '')::numeric, 0);
    v_extra_n  := greatest(0, ceil(v_adults::numeric / v_rooms) - v_base);
    v_free     := greatest(0, coalesce(nullif(v_room->>'freeChildrenPerRoom', '')::integer, 2) * v_rooms);

    -- children beyond the free slots pay, cheapest fees are the free ones
    select coalesce(sum(f.fee), 0) into v_child_pn
      from (
        select public._child_fee(v_room, a.age) as fee
          from (
            select (x.value)::numeric as age
              from jsonb_array_elements_text(case when jsonb_typeof(p->'childAges') = 'array' then p->'childAges' else '[]'::jsonb end) with ordinality as x(value, ord)
             where x.value ~ '^[0-9]+(\.[0-9]+)?$' and x.ord <= 6
          ) a
         order by 1
         offset v_free
      ) f;

    v_subtotal := ((v_room->>'price')::numeric + v_extra_n * v_extra_ad) * v_rooms * v_nights + v_child_pn * v_nights;
  else
    if jsonb_typeof(item->'price') <> 'number' then raise exception 'Item has no price' using errcode = 'P0001'; end if;
    if coalesce(p->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid or past date' using errcode = '22023'; end if;
    begin
      v_in := (p->>'date')::date;
    exception when others then
      raise exception 'Invalid or past date' using errcode = '22023';
    end;
    if v_in < v_today then raise exception 'Invalid or past date' using errcode = '22023'; end if;
    if v_type = 'package' and coalesce(item->>'priceMode', 'person') = 'package' then
      -- one price for the whole package (e.g. the honeymoon suite for the couple): head count is validated but does not change the price
      perform public._req_int(p->>'participants', 1, 50, 'participants');
      v_subtotal := (item->>'price')::numeric;
    elsif v_type in ('excursion', 'package') then
      v_subtotal := (item->>'price')::numeric * public._req_int(p->>'participants', 1, 50, 'participants');
    else
      perform public._req_int(p->>'passengers', 1, 50, 'passengers');
      v_subtotal := (item->>'price')::numeric;
    end if;
  end if;

  v_taxes   := round(v_subtotal * v_rate);
  v_total   := v_subtotal + v_taxes;
  v_deposit := round(v_total * 0.5);
  return jsonb_build_object(
    'subtotal', v_subtotal, 'taxes', v_taxes, 'total', v_total,
    'deposit', v_deposit, 'remaining', v_total - v_deposit, 'nights', v_nights
  );
end $$;

create or replace function public.create_booking(p jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid     uuid := (select auth.uid());
  v_type    text := p->>'type';
  v_item_id text;
  v_prop    public.properties;
  v_price   jsonb;
  v_prof    public.profiles;
  v_plan    text;
  v_data    jsonb;
  v_row     public.bookings;
begin
  if v_uid is null then raise exception 'Not authenticated' using errcode = '28000'; end if;
  if jsonb_typeof(p) <> 'object' then raise exception 'booking object required' using errcode = '22023'; end if;
  if coalesce(p->>'id', '') !~ '^[A-Za-z0-9_-]{3,64}$' then raise exception 'Invalid booking id' using errcode = '22023'; end if;
  if v_type not in ('hotel', 'excursion', 'transfer', 'package') then raise exception 'Unknown booking type' using errcode = '22023'; end if;
  if coalesce(p->>'currency', '') <> 'EGP' then raise exception 'Only EGP is supported' using errcode = '22023'; end if;

  v_item_id := p->>(case v_type when 'hotel' then 'hotelId' when 'excursion' then 'excursionId' when 'package' then 'packageId' else 'transferId' end);
  if v_item_id is null or v_item_id = '' then raise exception 'Missing item id' using errcode = '22023'; end if;

  select * into v_prop from public.properties
   where id = v_item_id and kind = v_type::public.property_kind and status = 'published';
  if not found then raise exception 'Item not found' using errcode = 'P0002'; end if;

  v_price := public.compute_booking_price(p, v_prop.data);
  if coalesce(p->>'total', '') !~ '^[0-9]+(\.[0-9]+)?$' or (p->>'total')::numeric <> (v_price->>'total')::numeric then
    raise exception 'price_changed' using errcode = 'P0001', detail = 'price_changed', hint = v_price->>'total';
  end if;

  if exists (select 1 from public.bookings where id = p->>'id') then
    raise exception 'Booking id already exists' using errcode = '23505';
  end if;

  v_plan := case when p->>'paymentPlan' = 'deposit' then 'deposit' else 'full' end;
  select * into v_prof from public.profiles where id = v_uid;

  -- everything the client sent, minus server-owned fields and anything that looks like card data
  v_data := (p - array['ownerUid','ownerStatus','ownerNote','adminNote','needsRefund','cancelledBy','cancelReason','cancelledAt',
                       'uid','status','createdAt','expiresAt','card','cardNumber','cvv','cvc','expiry'])
            || jsonb_build_object('paymentPlan', v_plan);
  if jsonb_typeof(v_data->'payment') = 'object' then v_data := v_data - 'payment'; end if;

  insert into public.bookings (
    id, user_id, property_id, owner_id, kind, status, payment_plan, currency,
    subtotal, taxes, total, deposit_amount, remaining_amount, amount_due_now,
    check_in, check_out, service_date, nights,
    guest_name, guest_email, guest_phone, data, expires_at
  ) values (
    p->>'id', v_uid, v_prop.id, v_prop.owner_id, v_type::public.property_kind, 'pending_payment', v_plan, 'EGP',
    (v_price->>'subtotal')::numeric, (v_price->>'taxes')::numeric, (v_price->>'total')::numeric,
    (v_price->>'deposit')::numeric, (v_price->>'remaining')::numeric,
    case when v_plan = 'deposit' then (v_price->>'deposit')::numeric else (v_price->>'total')::numeric end,
    case when v_type = 'hotel' then (p->>'checkin')::date end,
    case when v_type = 'hotel' then (p->>'checkout')::date end,
    case when v_type <> 'hotel' then (p->>'date')::date end,
    nullif(v_price->>'nights', '')::integer,
    left(coalesce(nullif(p->>'name', ''), v_prof.display_name), 120),
    left(coalesce(nullif(p->>'email', ''), v_prof.email), 254),
    left(coalesce(nullif(p->>'phone', ''), v_prof.phone), 30),
    v_data,
    now() + interval '2 hours'
  ) returning * into v_row;

  return jsonb_build_object('success', true, 'booking', public.booking_to_json(v_row));
end $$;

-- commission is read (and frozen on the booking) when the owner marks the service done
create or replace function public.owner_update_booking(p_id text, p_owner_status text, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid   uuid := (select auth.uid());
  v_admin boolean := (select public.is_super_admin());
  v_b     public.bookings;
  v_rate  numeric;
  v_comm  numeric;
  v_new   text := nullif(p_owner_status, 'new');
  v_change boolean := p_owner_status is not null;     -- a note-only save leaves the status alone
begin
  if p_owner_status is not null and p_owner_status not in ('new', 'confirmed', 'done', 'no_show') then
    raise exception 'Invalid status' using errcode = '22023';
  end if;
  select * into v_b from public.bookings where id = p_id for update;
  if not found or not (v_b.owner_id = v_uid or v_admin) then raise exception 'Booking not found' using errcode = 'P0002'; end if;
  if not v_admin and v_b.status <> 'completed' then
    raise exception 'Only paid bookings can be updated' using errcode = 'P0001';
  end if;
  if v_change and v_b.earned_at is not null and v_new is distinct from v_b.owner_status and not v_admin then
    raise exception 'Earnings were already recorded for this booking' using errcode = 'P0001';
  end if;

  if v_change and v_new = 'done' and v_b.earned_at is null and v_b.owner_id is not null and v_b.status = 'completed' then
    if coalesce(v_b.check_in, v_b.service_date) is null or coalesce(v_b.check_in, v_b.service_date) > (now() at time zone 'Africa/Cairo')::date then
      raise exception 'The service date has not passed yet' using errcode = 'P0001', detail = 'too_early';
    end if;
    select commission_rate into v_rate from public.profiles where id = v_b.owner_id;
    if v_rate is null then
      select case v_b.kind when 'hotel' then commission_hotel when 'excursion' then commission_excursion
                           when 'transfer' then commission_transfer when 'package' then commission_package else default_commission_rate end
        into v_rate from public.platform_settings where id = 1;
    end if;
    v_comm := round(v_b.subtotal * v_rate, 2);
    update public.bookings
       set owner_status = 'done', owner_note = left(coalesce(p_note, owner_note), 1000), earned_at = now(),
           commission_rate = v_rate, commission_amount = v_comm, owner_amount = v_b.subtotal - v_comm
     where id = p_id returning * into v_b;
  else
    update public.bookings
       set owner_status = case when v_change then v_new else owner_status end, owner_note = left(coalesce(p_note, owner_note), 1000)
     where id = p_id returning * into v_b;
  end if;
  return public.booking_to_json(v_b);
end $$;

-- dashboard role counts
create or replace function public.console_stats()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'roleCounts', (select coalesce(jsonb_object_agg(k, c), '{}'::jsonb) from (
        select case when role = 'super_admin' then 'super_admin'
                    else case owner_kinds[1] when 'hotel' then 'hotels_owner' when 'excursion' then 'trips_owner'
                                             when 'package' then 'packages_owner' when 'transfer' then 'transfers_owner' else 'restaurants_owner' end end as k, count(*) c
          from public.profiles where role <> 'user' group by 1) r),
    'revenue', (select coalesce(jsonb_object_agg(kind, s), '{}'::jsonb) from (
        select kind, sum(total) s from public.bookings
         where status = 'completed' and created_at >= now() - interval '365 days' group by kind) x),
    'revenueByType', (select coalesce(jsonb_object_agg(kind, s), '{}'::jsonb) from (
        select kind, sum(total) s from public.bookings
         where status = 'completed' and created_at >= now() - interval '30 days' group by kind) x),
    'bookings', (select count(*) from public.bookings where status <> 'pending_payment'),
    'last30',   (select count(*) from public.bookings where status <> 'pending_payment' and created_at >= now() - interval '30 days'),
    'series', (select jsonb_agg(jsonb_build_object('d', to_char(d.day, 'YYYY-MM-DD'), 'rev', coalesce(b.rev, 0), 'n', coalesce(b.n, 0)) order by d.day)
                 from generate_series(((now() at time zone 'Africa/Cairo')::date - 29), (now() at time zone 'Africa/Cairo')::date, interval '1 day') as d(day)
                 left join (select (created_at at time zone 'Africa/Cairo')::date as day,
                                   sum(total) filter (where status = 'completed') as rev, count(*) filter (where status = 'completed') as n
                              from public.bookings
                             where created_at >= now() - interval '31 days' and status <> 'pending_payment' group by 1) b
                   on b.day = d.day::date),
    'byStatus', (select coalesce(jsonb_object_agg(status, c), '{}'::jsonb) from (
        select status, count(*) c from public.bookings
         where status <> 'pending_payment' and created_at >= now() - interval '90 days' group by status) x),
    'needsRefund', (select count(*) from public.bookings where needs_refund),
    'payoutsOpen', (select jsonb_build_object('count', count(*), 'amount', coalesce(sum(amount), 0)) from public.payouts where status = 'requested'),
    'applications', (select count(*) from public.partner_applications where status = 'pending'),
    'messages', (select count(*) from public.contact_messages where status = 'new'),
    'items', (select coalesce(jsonb_object_agg(kind, c), '{}'::jsonb) from (
        select kind, count(*) c from public.properties where status <> 'archived' group by kind) x)
  );
end $$;

-- commission settings: a fifth value for packages (old 4-argument version dropped so the RPC name stays unambiguous)
drop function if exists public.admin_update_settings(numeric, numeric, numeric, numeric);
create or replace function public.admin_update_settings(p_hotel numeric, p_excursion numeric, p_transfer numeric, p_min_payout numeric, p_package numeric default null)
returns void language plpgsql security definer set search_path = '' as $$
declare v_pkg numeric;
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  select coalesce(p_package, commission_package * 100) into v_pkg from public.platform_settings where id = 1;
  if least(p_hotel, p_excursion, p_transfer, v_pkg) < 0 or greatest(p_hotel, p_excursion, p_transfer, v_pkg) > 100 or p_min_payout < 0 then
    raise exception 'Invalid values' using errcode = '22023';
  end if;
  update public.platform_settings
     set commission_hotel = p_hotel / 100, commission_excursion = p_excursion / 100, commission_transfer = p_transfer / 100,
         commission_package = v_pkg / 100, min_payout = p_min_payout, updated_at = now()
   where id = 1;
  perform public.audit('settings', 'platform', '1', jsonb_build_object('hotel', p_hotel, 'excursion', p_excursion, 'transfer', p_transfer, 'package', v_pkg, 'min_payout', p_min_payout));
end $$;
grant execute on function public.admin_update_settings(numeric, numeric, numeric, numeric, numeric) to authenticated;


-- ==============================================================================================================
-- migration: 20261107000100_balance_guard.sql
-- ==============================================================================================================
-- Deposit bookings: the owner cannot mark the service "done" (which records the earnings) until the customer has paid the remaining balance online.
-- Super admin can still override. Nothing else changes.
create or replace function public.owner_update_booking(p_id text, p_owner_status text, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid   uuid := (select auth.uid());
  v_admin boolean := (select public.is_super_admin());
  v_b     public.bookings;
  v_rate  numeric;
  v_comm  numeric;
  v_new   text := nullif(p_owner_status, 'new');
  v_change boolean := p_owner_status is not null;     -- a note-only save leaves the status alone
begin
  if p_owner_status is not null and p_owner_status not in ('new', 'confirmed', 'done', 'no_show') then
    raise exception 'Invalid status' using errcode = '22023';
  end if;
  select * into v_b from public.bookings where id = p_id for update;
  if not found or not (v_b.owner_id = v_uid or v_admin) then raise exception 'Booking not found' using errcode = 'P0002'; end if;
  if not v_admin and v_b.status <> 'completed' then
    raise exception 'Only paid bookings can be updated' using errcode = 'P0001';
  end if;
  if v_change and v_b.earned_at is not null and v_new is distinct from v_b.owner_status and not v_admin then
    raise exception 'Earnings were already recorded for this booking' using errcode = 'P0001';
  end if;

  if v_change and v_new = 'done' and v_b.earned_at is null and v_b.owner_id is not null and v_b.status = 'completed' then
    if coalesce(v_b.check_in, v_b.service_date) is null or coalesce(v_b.check_in, v_b.service_date) > (now() at time zone 'Africa/Cairo')::date then
      raise exception 'The service date has not passed yet' using errcode = 'P0001', detail = 'too_early';
    end if;
    -- the remaining balance of a deposit booking is collected ONLINE by the platform before the service: no execution / earnings until it is paid
    if v_b.payment_plan = 'deposit' and v_b.remaining_amount > 0 and coalesce(v_b.data->>'balanceStatus', '') <> 'paid' and not v_admin then
      raise exception 'The remaining balance has not been paid yet' using errcode = 'P0001', detail = 'balance_due';
    end if;
    select commission_rate into v_rate from public.profiles where id = v_b.owner_id;
    if v_rate is null then
      select case v_b.kind when 'hotel' then commission_hotel when 'excursion' then commission_excursion
                           when 'transfer' then commission_transfer when 'package' then commission_package else default_commission_rate end
        into v_rate from public.platform_settings where id = 1;
    end if;
    v_comm := round(v_b.subtotal * v_rate, 2);
    update public.bookings
       set owner_status = 'done', owner_note = left(coalesce(p_note, owner_note), 1000), earned_at = now(),
           commission_rate = v_rate, commission_amount = v_comm, owner_amount = v_b.subtotal - v_comm
     where id = p_id returning * into v_b;
  else
    update public.bookings
       set owner_status = case when v_change then v_new else owner_status end, owner_note = left(coalesce(p_note, owner_note), 1000)
     where id = p_id returning * into v_b;
  end if;
  return public.booking_to_json(v_b);
end $$;


-- ==============================================================================================================
-- migration: 20261107000200_balance_deadline.sql
-- ==============================================================================================================
-- Remaining-balance deadline for deposit bookings.
--  * the customer must pay the rest `balance_due_hours` before the service date (never less than 24h after the booking is confirmed)
--  * public.balance_job() (called hourly by the payments Worker's cron) hands out 72h / 24h reminders and auto-cancels unpaid bookings
--    when platform_settings.balance_auto_cancel is true. The deposit is kept (needs_refund stays false) — the admin can refund manually.
-- Change the rules with:  update public.platform_settings set balance_due_hours = 72, balance_auto_cancel = false where id = 1;

alter table public.platform_settings
  add column if not exists balance_due_hours   int     not null default 48 check (balance_due_hours between 0 and 720),
  add column if not exists balance_auto_cancel boolean not null default true;

alter table public.bookings
  add column if not exists balance_due_at     timestamptz,
  add column if not exists balance_reminders  smallint not null default 0;

create or replace function public.set_balance_due_at() returns trigger language plpgsql set search_path = '' as $$
declare v_day date := coalesce(new.check_in, new.service_date); v_h int;
begin
  if new.payment_plan = 'deposit' and new.status = 'completed' and new.remaining_amount > 0 and new.balance_due_at is null and v_day is not null then
    select balance_due_hours into v_h from public.platform_settings where id = 1;
    new.balance_due_at := greatest(((v_day::timestamp) at time zone 'Africa/Cairo') - make_interval(hours => coalesce(v_h, 48)), now() + interval '24 hours');
  end if;
  return new;
end $$;
drop trigger if exists bookings_balance_due on public.bookings;
create trigger bookings_balance_due before insert or update of status, payment_plan on public.bookings
  for each row execute function public.set_balance_due_at();

-- existing unpaid deposit bookings whose service is still ahead get a deadline too (past services are left alone)
update public.bookings
   set balance_due_at = greatest(((coalesce(check_in, service_date))::timestamp at time zone 'Africa/Cairo') - interval '48 hours', now() + interval '24 hours')
 where payment_plan = 'deposit' and status = 'completed' and remaining_amount > 0 and balance_due_at is null
   and coalesce(data->>'balanceStatus', '') <> 'paid'
   and coalesce(check_in, service_date) > (now() at time zone 'Africa/Cairo')::date;

-- the booking JSON now carries balanceDueAt (shown to the customer next to "pay the rest")
create or replace function public.booking_to_json(b public.bookings)
returns jsonb language sql stable set search_path = '' as $$
  select b.data || jsonb_strip_nulls(jsonb_build_object(
    'id', b.id, 'type', b.kind, 'status', b.status, 'uid', b.user_id, 'ownerUid', b.owner_id,
    'total', b.total, 'subtotal', b.subtotal, 'taxes', b.taxes,
    'depositAmount', b.deposit_amount, 'remainingAmount', b.remaining_amount, 'amountDueNow', b.amount_due_now,
    'paymentPlan', b.payment_plan, 'currency', b.currency, 'nights', b.nights,
    'checkin', b.check_in, 'checkout', b.check_out, 'date', b.service_date,
    'reviewed', b.reviewed, 'ownerStatus', b.owner_status, 'ownerNote', b.owner_note, 'adminNote', b.admin_note,
    'needsRefund', case when b.needs_refund then true end,
    'cancelledAt', b.cancelled_at, 'cancelReason', b.cancel_reason, 'balanceDueAt', b.balance_due_at,
    'createdAt', b.created_at, 'expiresAt', b.expires_at,
    'earning', case when b.earned_at is not null then jsonb_build_object(
        'gross', b.subtotal, 'rate', round(coalesce(b.commission_rate, 0) * 100, 2), 'commission', b.commission_amount,
        'net', b.owner_amount, 'void', b.earning_void, 'at', b.earned_at) end
  ))
$$;

create or replace function public.balance_job() returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_auto boolean; v_cancel jsonb; v_rem jsonb;
begin
  select balance_auto_cancel into v_auto from public.platform_settings where id = 1;
  with c as (
    update public.bookings
       set status = 'cancelled', cancelled_at = now(), cancel_reason = 'balance_unpaid', needs_refund = false
     where coalesce(v_auto, false) and status = 'completed' and payment_plan = 'deposit' and remaining_amount > 0
       and coalesce(data->>'balanceStatus', '') <> 'paid' and balance_due_at is not null and balance_due_at <= now()
       and owner_status is distinct from 'done'
    returning id, data->>'email' as email, data->>'name' as name, kind, remaining_amount, currency
  ) select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) into v_cancel from c;

  with r as (
    select id, case when balance_due_at - now() <= interval '24 hours' then 2 else 1 end as n
      from public.bookings
     where status = 'completed' and payment_plan = 'deposit' and remaining_amount > 0 and coalesce(data->>'balanceStatus', '') <> 'paid'
       and balance_due_at is not null and balance_due_at > now() and balance_due_at - now() <= interval '72 hours'
       and balance_reminders < case when balance_due_at - now() <= interval '24 hours' then 2 else 1 end
       for update skip locked
  ), u as (
    update public.bookings b set balance_reminders = r.n from r where b.id = r.id
    returning b.id, b.data->>'email' as email, b.data->>'name' as name, b.kind, b.remaining_amount, b.currency, b.balance_due_at as due_at, r.n
  ) select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) into v_rem from u;

  return jsonb_build_object('cancelled', v_cancel, 'reminders', v_rem);
end $$;
revoke all on function public.balance_job() from public, anon, authenticated;
grant execute on function public.balance_job() to service_role;


-- ==============================================================================================================
-- migration: 20261108000100_autopay.sql
-- ==============================================================================================================
-- Automatic collection of the remaining balance from the card the customer agreed to (Kashier agreement + token, merchant-initiated "CONTAUTH" charge).
-- Nothing happens unless the payments Worker has AUTO_BALANCE=on and the customer ticked the consent box at checkout.
-- Tokens live in a table nobody but the service role can read.

create table if not exists public.booking_autopay (
  booking_id      text primary key,
  user_id         uuid,
  consented_at    timestamptz,
  card_token      text,
  agreement_id    text,
  masked_card     text,
  attempts        smallint not null default 0,
  last_attempt_at timestamptz,
  last_error      text,
  updated_at      timestamptz not null default now()
);
alter table public.booking_autopay enable row level security;      -- no policies: not readable or writable through the API
revoke all on public.booking_autopay from public, anon, authenticated;

create or replace function public.autopay_upsert(p_id text, p_uid uuid, p_patch jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.booking_autopay (booking_id, user_id, consented_at, card_token, agreement_id, masked_card, last_error)
  values (p_id, p_uid, case when coalesce((p_patch->>'consent')::boolean, false) then now() end,
          p_patch->>'card_token', p_patch->>'agreement_id', p_patch->>'masked_card', p_patch->>'last_error')
  on conflict (booking_id) do update set
    consented_at = coalesce(public.booking_autopay.consented_at, excluded.consented_at),
    card_token   = coalesce(excluded.card_token, public.booking_autopay.card_token),
    agreement_id = coalesce(excluded.agreement_id, public.booking_autopay.agreement_id),
    masked_card  = coalesce(excluded.masked_card, public.booking_autopay.masked_card),
    last_error   = coalesce(excluded.last_error, public.booking_autopay.last_error),
    updated_at   = now();
end $$;
create or replace function public.autopay_get(p_id text) returns jsonb language sql security definer set search_path = '' as $$
  select to_jsonb(a) from public.booking_autopay a where a.booking_id = p_id
$$;
revoke all on function public.autopay_upsert(text, uuid, jsonb), public.autopay_get(text) from public, anon, authenticated;
grant execute on function public.autopay_upsert(text, uuid, jsonb), public.autopay_get(text) to service_role;

create or replace function public.balance_job() returns jsonb language plpgsql security definer set search_path = '' as $$
declare v_auto boolean; v_cancel jsonb; v_rem jsonb; v_pay jsonb;
begin
  select balance_auto_cancel into v_auto from public.platform_settings where id = 1;
  with c as (
    update public.bookings
       set status = 'cancelled', cancelled_at = now(), cancel_reason = 'balance_unpaid', needs_refund = false
     where coalesce(v_auto, false) and status = 'completed' and payment_plan = 'deposit' and remaining_amount > 0
       and coalesce(data->>'balanceStatus', '') <> 'paid' and balance_due_at is not null and balance_due_at <= now()
       and owner_status is distinct from 'done'
    returning id, data->>'email' as email, data->>'name' as name, kind, remaining_amount, currency
  ) select coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb) into v_cancel from c;

  with r as (
    select id, case when balance_due_at - now() <= interval '24 hours' then 2 else 1 end as n
      from public.bookings
     where status = 'completed' and payment_plan = 'deposit' and remaining_amount > 0 and coalesce(data->>'balanceStatus', '') <> 'paid'
       and balance_due_at is not null and balance_due_at > now() and balance_due_at - now() <= interval '72 hours'
       and balance_reminders < case when balance_due_at - now() <= interval '24 hours' then 2 else 1 end
       and not (balance_due_at - now() <= interval '24 hours' and exists (select 1 from public.booking_autopay ap where ap.booking_id = bookings.id and ap.card_token is not null and ap.agreement_id is not null))
       for update skip locked
  ), u as (
    update public.bookings b set balance_reminders = r.n from r where b.id = r.id
    returning b.id, b.data->>'email' as email, b.data->>'name' as name, b.kind, b.remaining_amount, b.currency, b.balance_due_at as due_at, r.n,
      (select ap.masked_card from public.booking_autopay ap where ap.booking_id = b.id and ap.card_token is not null and ap.agreement_id is not null) as autopay_card
  ) select coalesce(jsonb_agg(to_jsonb(u)), '[]'::jsonb) into v_rem from u;

  -- automatic charges: within 24h of the deadline (and at least 12h after the customer agreed), a second try inside the last 6h
  with a as (
    select b.id, ap.user_id, ap.card_token, ap.agreement_id
      from public.bookings b join public.booking_autopay ap on ap.booking_id = b.id
     where b.status = 'completed' and b.payment_plan = 'deposit' and b.remaining_amount > 0 and coalesce(b.data->>'balanceStatus', '') <> 'paid'
       and ap.card_token is not null and ap.agreement_id is not null and ap.consented_at <= now() - interval '12 hours'
       and b.balance_due_at is not null and b.balance_due_at > now() and b.balance_due_at - now() <= interval '24 hours'
       and ap.attempts < case when b.balance_due_at - now() <= interval '6 hours' then 2 else 1 end
       and (ap.last_attempt_at is null or ap.last_attempt_at < now() - interval '3 hours')
       for update of ap skip locked
  ), u as (
    update public.booking_autopay ap set attempts = ap.attempts + 1, last_attempt_at = now(), updated_at = now() from a where ap.booking_id = a.id
    returning ap.booking_id as id, a.user_id as uid, a.card_token, a.agreement_id, ap.masked_card
  ) select coalesce(jsonb_agg(to_jsonb(u) || jsonb_build_object('remaining_amount', b.remaining_amount, 'currency', b.currency, 'email', b.data->>'email', 'name', b.data->>'name', 'due_at', b.balance_due_at)), '[]'::jsonb)
      into v_pay from u join public.bookings b on b.id = u.id;

  return jsonb_build_object('cancelled', v_cancel, 'reminders', v_rem, 'autopay', v_pay);
end $$;
revoke all on function public.balance_job() from public, anon, authenticated;
grant execute on function public.balance_job() to service_role;


-- ==============================================================================================================
-- migration: 20261110000100_autopay_stop.sql
-- ==============================================================================================================
-- Autopay: an unconfirmed charge (gateway timeout / PENDING / UNKNOWN) must never be retried automatically (risk of a double charge).
-- autopay_upsert now accepts {"stop": true} which uses up the remaining attempts; the webhook / reconciliation settles the booking.
create or replace function public.autopay_upsert(p_id text, p_uid uuid, p_patch jsonb) returns void
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.booking_autopay (booking_id, user_id, consented_at, card_token, agreement_id, masked_card, last_error, attempts)
  values (p_id, p_uid, case when coalesce((p_patch->>'consent')::boolean, false) then now() end,
          p_patch->>'card_token', p_patch->>'agreement_id', p_patch->>'masked_card', p_patch->>'last_error',
          case when coalesce((p_patch->>'stop')::boolean, false) then 9 else 0 end)
  on conflict (booking_id) do update set
    consented_at = coalesce(public.booking_autopay.consented_at, excluded.consented_at),
    card_token   = coalesce(excluded.card_token, public.booking_autopay.card_token),
    agreement_id = coalesce(excluded.agreement_id, public.booking_autopay.agreement_id),
    masked_card  = coalesce(excluded.masked_card, public.booking_autopay.masked_card),
    last_error   = coalesce(excluded.last_error, public.booking_autopay.last_error),
    attempts     = case when coalesce((p_patch->>'stop')::boolean, false) then 9 else public.booking_autopay.attempts end,
    updated_at   = now();
end $$;


-- ==============================================================================================================
-- migration: 20261110000200_deposit_rules.sql
-- ==============================================================================================================
-- Deposit rules:
--  * the balance deadline is 24h before the service date (was 48h)
--  * a deposit is only accepted when the service is at least 2 days away (a booking for tomorrow or sooner must be paid in full)
alter table public.platform_settings alter column balance_due_hours set default 24;
update public.platform_settings set balance_due_hours = 24 where id = 1 and balance_due_hours = 48;
-- unpaid deposit bookings that still have the old 48h-based deadline get the 24h one (never earlier than 24h from now)
update public.bookings
   set balance_due_at = greatest(((coalesce(check_in, service_date))::timestamp at time zone 'Africa/Cairo') - interval '24 hours', now() + interval '24 hours')
 where payment_plan = 'deposit' and status = 'completed' and remaining_amount > 0 and balance_due_at is not null and balance_due_at > now()
   and coalesce(data->>'balanceStatus', '') <> 'paid';

create or replace function public.guard_deposit_date() returns trigger language plpgsql set search_path = '' as $$
declare v_day date := coalesce(new.check_in, new.service_date);
begin
  if new.payment_plan = 'deposit' and tg_op = 'INSERT' and v_day is not null
     and v_day >= (now() at time zone 'Africa/Cairo')::date and v_day < ((now() at time zone 'Africa/Cairo')::date + 2) then
    raise exception 'deposit_not_allowed' using errcode = 'P0001', detail = 'deposit_not_allowed',
      hint = 'A booking for tomorrow or sooner must be paid in full';
  end if;
  return new;
end $$;
drop trigger if exists bookings_deposit_date on public.bookings;
create trigger bookings_deposit_date before insert on public.bookings
  for each row execute function public.guard_deposit_date();


-- ==============================================================================================================
-- migration: 20261111000100_owner_collects_balance.sql
-- ==============================================================================================================
-- Owner-collects-balance model (2026-11-11)
--  * The platform collects ONLY the deposit (50% of the pre-tax price) or the full price online. Taxes and the Kashier gateway fee are charged
--    on top of that collected amount only. The remainder of a deposit booking is paid by the guest directly to the hotel / trip / transfer provider.
--  * Commission = rate x the full pre-tax price, fixed when the booking is created and deducted from what the platform holds:
--        platform pays the owner   owner_amount = collected_base - commission
--        owner collects on site    remaining_amount
--    (so the owner's total = pre-tax price - commission). The owner never sees the commission itself, only these two figures.
--  * No online balance payment any more: reminders / auto-cancel / auto-charge only apply to old ('legacy') bookings.
-- Run after 20261110000200_deposit_rules.sql.

alter table public.platform_settings
  add column if not exists gateway_fee_rate  numeric(5,4) not null default 0.0275 check (gateway_fee_rate >= 0 and gateway_fee_rate < 0.2),   -- Kashier cards: 2.75%
  add column if not exists gateway_fixed_fee numeric(8,2) not null default 3 check (gateway_fixed_fee >= 0),                                      -- + EGP 3 per transaction
  add column if not exists gateway_fee_vat   numeric(5,4) not null default 0.14 check (gateway_fee_vat >= 0 and gateway_fee_vat < 1);               -- + 14% VAT on the fee only
alter table public.bookings
  add column if not exists gateway_fee   numeric(12,2) not null default 0 check (gateway_fee >= 0),
  add column if not exists pricing_model text not null default 'legacy' check (pricing_model in ('legacy', 'v2'));

-- a deposit is fine for any date now (nothing has to be collected online later)
drop trigger if exists bookings_deposit_date on public.bookings;

-- the old balance deadline / reminders / auto-cancel only ever touch legacy bookings
create or replace function public.set_balance_due_at() returns trigger language plpgsql set search_path = '' as $$
declare v_day date := coalesce(new.check_in, new.service_date); v_h int;
begin
  if new.pricing_model = 'legacy' and new.payment_plan = 'deposit' and new.status = 'completed' and new.remaining_amount > 0 and new.balance_due_at is null and v_day is not null then
    select balance_due_hours into v_h from public.platform_settings where id = 1;
    new.balance_due_at := greatest(((v_day::timestamp) at time zone 'Africa/Cairo') - make_interval(hours => coalesce(v_h, 24)), now() + interval '24 hours');
  end if;
  return new;
end $$;

-- public prices the app needs to show the guest the exact amount (same numbers the server checks)
create or replace function public.public_pricing() returns jsonb language sql stable security definer set search_path = '' as $$
  select jsonb_build_object('gatewayFeeRate', gateway_fee_rate, 'gatewayFixedFee', gateway_fixed_fee, 'gatewayFeeVat', gateway_fee_vat, 'taxHotel', 0.10, 'taxOther', 0.05, 'depositRatio', 0.5)
    from public.platform_settings where id = 1
$$;
grant execute on function public.public_pricing() to anon, authenticated;

create or replace function public.compute_booking_price(p jsonb, item jsonb)
returns jsonb language plpgsql stable set search_path = '' as $$
declare
  v_type       text := p->>'type';
  v_today      date := (now() at time zone 'Africa/Cairo')::date;
  v_rate       numeric;
  v_subtotal   numeric;
  v_taxes      numeric;
  v_total      numeric;
  v_deposit    numeric;
  v_plan       text := case when p->>'paymentPlan' = 'deposit' then 'deposit' else 'full' end;
  v_f          numeric;
  v_fx         numeric;
  v_vat        numeric;
  v_coll       numeric;
  v_pay        numeric;
  v_fee        numeric;
  v_onsite     numeric;
  v_nights     integer;
  v_in         date;
  v_out        date;
  v_day        date;
  v_adults     integer;
  v_children   integer;
  v_rooms      integer;
  v_list       jsonb;
  v_room       jsonb;
  v_idx        integer := -1;
  v_want       text[];
  v_base       numeric;
  v_extra_ad   numeric;
  v_extra_n    numeric;
  v_free       integer;
  v_child_pn   numeric := 0;
  v_blocked    jsonb;
begin
  if v_type not in ('hotel', 'excursion', 'transfer', 'package') then
    raise exception 'Unknown booking type' using errcode = '22023';
  end if;
  v_rate := case v_type when 'hotel' then 0.10 else 0.05 end;

  if v_type = 'hotel' then
    if coalesce(p->>'checkin', '') !~ '^\d{4}-\d{2}-\d{2}$' or coalesce(p->>'checkout', '') !~ '^\d{4}-\d{2}-\d{2}$' then
      raise exception 'Invalid dates' using errcode = '22023';
    end if;
    begin
      v_in := (p->>'checkin')::date;
      v_out := (p->>'checkout')::date;
    exception when others then
      raise exception 'Invalid dates' using errcode = '22023';
    end;
    if v_in < v_today then raise exception 'Check-in date is in the past' using errcode = '22023'; end if;
    if v_out <= v_in then raise exception 'Check-out must be after check-in' using errcode = '22023'; end if;
    v_nights := greatest(1, v_out - v_in);
    if v_nights > 60 then raise exception 'Stay too long' using errcode = '22023'; end if;

    v_adults   := public._req_int(p->>'adults', 1, 10, 'adults');
    v_children := public._req_int(coalesce(p->>'children', '0'), 0, 6, 'children');
    v_rooms    := public._req_int(p->>'rooms', 1, 5, 'rooms');

    v_list := case when jsonb_typeof(item->'rooms') = 'array' then item->'rooms' else '[]'::jsonb end;
    if jsonb_typeof(p->'roomIndex') = 'number' and (p->>'roomIndex') ~ '^[0-9]+$' then
      v_idx := (p->>'roomIndex')::integer;
    else
      v_want := case when jsonb_typeof(p->'roomType') = 'object'
                     then array(select value from jsonb_each_text(p->'roomType'))
                     else array[p->>'roomType'] end;
      select (t.ord - 1)::integer into v_idx
        from jsonb_array_elements(v_list) with ordinality as t(r, ord)
       where exists (
               select 1 from jsonb_each_text(case when jsonb_typeof(t.r->'type') = 'object' then t.r->'type' else '{}'::jsonb end) e
                where e.value = any (v_want)
             )
          or (jsonb_typeof(t.r->'type') = 'string' and (t.r->>'type') = any (v_want))
       order by t.ord
       limit 1;
      v_idx := coalesce(v_idx, -1);
    end if;
    v_room := case when v_idx >= 0 then v_list->v_idx end;
    if v_room is null or jsonb_typeof(v_room->'price') <> 'number' then
      raise exception 'Room not found' using errcode = '22023';
    end if;

    v_blocked := case when jsonb_typeof(item->'unavailableDates') = 'array' then item->'unavailableDates' else '[]'::jsonb end;
    for i in 0 .. v_nights - 1 loop
      v_day := v_in + i;
      if v_blocked ? to_char(v_day, 'YYYY-MM-DD') then
        raise exception 'Selected dates are not available' using errcode = 'P0001', detail = 'unavailable';
      end if;
    end loop;

    v_base     := coalesce(nullif(v_room->>'baseOccupancy', '')::numeric, 0);
    if v_base = 0 then v_base := 2; end if;
    v_extra_ad := coalesce(nullif(v_room->>'extraAdultFee', '')::numeric, 0);
    v_extra_n  := greatest(0, ceil(v_adults::numeric / v_rooms) - v_base);
    v_free     := greatest(0, coalesce(nullif(v_room->>'freeChildrenPerRoom', '')::integer, 2) * v_rooms);

    -- children beyond the free slots pay, cheapest fees are the free ones
    select coalesce(sum(f.fee), 0) into v_child_pn
      from (
        select public._child_fee(v_room, a.age) as fee
          from (
            select (x.value)::numeric as age
              from jsonb_array_elements_text(case when jsonb_typeof(p->'childAges') = 'array' then p->'childAges' else '[]'::jsonb end) with ordinality as x(value, ord)
             where x.value ~ '^[0-9]+(\.[0-9]+)?$' and x.ord <= 6
          ) a
         order by 1
         offset v_free
      ) f;

    v_subtotal := ((v_room->>'price')::numeric + v_extra_n * v_extra_ad) * v_rooms * v_nights + v_child_pn * v_nights;
  else
    if jsonb_typeof(item->'price') <> 'number' then raise exception 'Item has no price' using errcode = 'P0001'; end if;
    if coalesce(p->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Invalid or past date' using errcode = '22023'; end if;
    begin
      v_in := (p->>'date')::date;
    exception when others then
      raise exception 'Invalid or past date' using errcode = '22023';
    end;
    if v_in < v_today then raise exception 'Invalid or past date' using errcode = '22023'; end if;
    if v_type = 'package' and coalesce(item->>'priceMode', 'person') = 'package' then
      -- one price for the whole package (e.g. the honeymoon suite for the couple): head count is validated but does not change the price
      perform public._req_int(p->>'participants', 1, 50, 'participants');
      v_subtotal := (item->>'price')::numeric;
    elsif v_type in ('excursion', 'package') then
      v_subtotal := (item->>'price')::numeric * public._req_int(p->>'participants', 1, 50, 'participants');
    else
      perform public._req_int(p->>'passengers', 1, 50, 'passengers');
      v_subtotal := (item->>'price')::numeric;
    end if;
  end if;

  -- Owner-collects-balance model: the platform only collects the deposit (or everything) online. Taxes and the gateway fee are
  -- charged on top of THAT amount only; the rest (v_onsite) is paid to the service provider at the venue.
  select gateway_fee_rate, gateway_fixed_fee, gateway_fee_vat into v_f, v_fx, v_vat from public.platform_settings where id = 1;
  v_f := coalesce(v_f, 0); v_fx := coalesce(v_fx, 0); v_vat := coalesce(v_vat, 0);
  v_coll    := case when v_plan = 'deposit' then round(v_subtotal * 0.5) else v_subtotal end;
  v_onsite  := v_subtotal - v_coll;
  v_taxes   := round(v_coll * v_rate);
  -- Kashier takes (rate x charged + fixed) plus VAT on that fee; gross the charge up so we net base + tax exactly
  v_pay     := round((v_coll + v_taxes + v_fx * (1 + v_vat)) / (1 - v_f * (1 + v_vat)));
  v_fee     := v_pay - v_coll - v_taxes;
  return jsonb_build_object(
    'subtotal', v_subtotal, 'taxes', v_taxes, 'fee', v_fee, 'collected', v_coll, 'due', v_pay,
    'remaining', v_onsite, 'total', v_pay + v_onsite,
    'deposit', case when v_plan = 'deposit' then v_pay else 0 end, 'nights', v_nights
  );
end $$;

create or replace function public.create_booking(p jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid     uuid := (select auth.uid());
  v_type    text := p->>'type';
  v_item_id text;
  v_prop    public.properties;
  v_price   jsonb;
  v_prof    public.profiles;
  v_plan    text;
  v_data    jsonb;
  v_row     public.bookings;
  v_rate    numeric;
  v_comm    numeric;
begin
  if v_uid is null then raise exception 'Not authenticated' using errcode = '28000'; end if;
  if jsonb_typeof(p) <> 'object' then raise exception 'booking object required' using errcode = '22023'; end if;
  if coalesce(p->>'id', '') !~ '^[A-Za-z0-9_-]{3,64}$' then raise exception 'Invalid booking id' using errcode = '22023'; end if;
  if v_type not in ('hotel', 'excursion', 'transfer', 'package') then raise exception 'Unknown booking type' using errcode = '22023'; end if;
  if coalesce(p->>'currency', '') <> 'EGP' then raise exception 'Only EGP is supported' using errcode = '22023'; end if;

  v_item_id := p->>(case v_type when 'hotel' then 'hotelId' when 'excursion' then 'excursionId' when 'package' then 'packageId' else 'transferId' end);
  if v_item_id is null or v_item_id = '' then raise exception 'Missing item id' using errcode = '22023'; end if;

  select * into v_prop from public.properties
   where id = v_item_id and kind = v_type::public.property_kind and status = 'published';
  if not found then raise exception 'Item not found' using errcode = 'P0002'; end if;

  v_price := public.compute_booking_price(p, v_prop.data);
  if coalesce(p->>'total', '') !~ '^[0-9]+(\.[0-9]+)?$' or (p->>'total')::numeric <> (v_price->>'total')::numeric then
    raise exception 'price_changed' using errcode = 'P0001', detail = 'price_changed', hint = v_price->>'total';
  end if;

  if exists (select 1 from public.bookings where id = p->>'id') then
    raise exception 'Booking id already exists' using errcode = '23505';
  end if;

  v_plan := case when p->>'paymentPlan' = 'deposit' then 'deposit' else 'full' end;
  select * into v_prof from public.profiles where id = v_uid;

  -- the platform's commission is fixed NOW on the full pre-tax price; it comes out of what we collect, never off the on-site part
  select commission_rate into v_rate from public.profiles where id = v_prop.owner_id;
  if v_rate is null then
    select case v_type when 'hotel' then commission_hotel when 'excursion' then commission_excursion
                       when 'transfer' then commission_transfer when 'package' then commission_package else default_commission_rate end
      into v_rate from public.platform_settings where id = 1;
  end if;
  v_comm := round((v_price->>'subtotal')::numeric * coalesce(v_rate, 0), 2);

  -- everything the client sent, minus server-owned fields and anything that looks like card data
  v_data := (p - array['ownerUid','ownerStatus','ownerNote','adminNote','needsRefund','cancelledBy','cancelReason','cancelledAt',
                       'uid','status','createdAt','expiresAt','card','cardNumber','cvv','cvc','expiry'])
            || jsonb_build_object('paymentPlan', v_plan);
  if jsonb_typeof(v_data->'payment') = 'object' then v_data := v_data - 'payment'; end if;

  insert into public.bookings (
    id, user_id, property_id, owner_id, kind, status, payment_plan, currency,
    subtotal, taxes, gateway_fee, total, deposit_amount, remaining_amount, amount_due_now,
    pricing_model, commission_rate, commission_amount, owner_amount,
    check_in, check_out, service_date, nights,
    guest_name, guest_email, guest_phone, data, expires_at
  ) values (
    p->>'id', v_uid, v_prop.id, v_prop.owner_id, v_type::public.property_kind, 'pending_payment', v_plan, 'EGP',
    (v_price->>'subtotal')::numeric, (v_price->>'taxes')::numeric, (v_price->>'fee')::numeric, (v_price->>'total')::numeric,
    (v_price->>'deposit')::numeric, (v_price->>'remaining')::numeric, (v_price->>'due')::numeric,
    'v2', v_rate, v_comm, (v_price->>'collected')::numeric - v_comm,
    case when v_type = 'hotel' then (p->>'checkin')::date end,
    case when v_type = 'hotel' then (p->>'checkout')::date end,
    case when v_type <> 'hotel' then (p->>'date')::date end,
    nullif(v_price->>'nights', '')::integer,
    left(coalesce(nullif(p->>'name', ''), v_prof.display_name), 120),
    left(coalesce(nullif(p->>'email', ''), v_prof.email), 254),
    left(coalesce(nullif(p->>'phone', ''), v_prof.phone), 30),
    v_data,
    now() + interval '2 hours'
  ) returning * into v_row;

  return jsonb_build_object('success', true, 'booking', public.booking_to_json(v_row));
end $$;

create or replace function public.finalize_booking_payment(p_id text, p_gateway_status text, p_extra jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_b     public.bookings;
  v_s     text := upper(coalesce(p_gateway_status, ''));
  v_extra jsonb := coalesce(p_extra, '{}'::jsonb) - array['status', 'uid', 'ownerUid', 'total', 'subtotal', 'currency'];
  v_data  jsonb;
begin
  select * into v_b from public.bookings where id = p_id for update;
  if not found then return null; end if;

  if v_s in ('SUCCESS', 'PAID', 'CAPTURED') then
    if v_b.status <> 'pending_payment' then
      return jsonb_build_object('status', v_b.status, 'created', false);       -- already finalized: never twice
    end if;

    -- the confirming charge only ever covers amount_due_now (deposit, or the full total)
    v_data := (v_b.data - array['lastPaymentStatus', 'paymentFlag'])
              || jsonb_build_object('paidAmount', v_b.amount_due_now, 'paidAt', now(), 'checkoutAt', v_b.created_at)
              || case when v_b.payment_plan = 'deposit' and v_b.remaining_amount > 0
                      then jsonb_build_object('balanceAmount', v_b.remaining_amount,
                                              'balanceStatus', case when v_b.pricing_model = 'v2' then 'onsite' else 'due' end)   -- v2: paid to the provider at the venue
                      else jsonb_build_object('balanceStatus', 'paid') end
              || v_extra;

    update public.bookings
       set status = 'completed', confirmed_at = now(), created_at = now(), expires_at = null,
           data = v_data
     where id = p_id;

    if v_b.user_id is not null then
      update public.profiles
         set completed_bookings = completed_bookings + 1,
             total_spent = total_spent + case when v_b.pricing_model = 'v2' then v_b.amount_due_now else v_b.total end,
             loyalty_tier = public.loyalty_tier_for(completed_bookings + 1)
       where id = v_b.user_id;
      insert into public.notifications (user_id, icon, title, msg)
      values (v_b.user_id, 'fa-circle-check', 'Booking confirmed', 'Your booking ' || v_b.id || ' is confirmed.');
    end if;
    if v_b.owner_id is not null then
      insert into public.notifications (user_id, icon, title, msg)
      values (v_b.owner_id, 'fa-calendar-plus', 'New booking', 'New booking ' || v_b.id || ' on one of your listings.');
    end if;
    return jsonb_build_object('status', 'completed', 'created', true);
  end if;

  if v_s in ('FAILED', 'FAILURE', 'DECLINED') then
    if v_b.status = 'pending_payment' then
      -- the checkout session stays open so the guest can retry with another card
      update public.bookings set data = data || '{"lastPaymentStatus":"failed"}'::jsonb where id = p_id;
      return jsonb_build_object('status', 'failed', 'created', false);
    end if;
    return jsonb_build_object('status', v_b.status, 'created', false);
  end if;

  return jsonb_build_object('status', v_b.status, 'created', false);          -- still pending at the gateway
end $$;

create or replace function public.owner_update_booking(p_id text, p_owner_status text, p_note text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid   uuid := (select auth.uid());
  v_admin boolean := (select public.is_super_admin());
  v_b     public.bookings;
  v_rate  numeric;
  v_comm  numeric;
  v_new   text := nullif(p_owner_status, 'new');
  v_change boolean := p_owner_status is not null;     -- a note-only save leaves the status alone
begin
  if p_owner_status is not null and p_owner_status not in ('new', 'confirmed', 'done', 'no_show') then
    raise exception 'Invalid status' using errcode = '22023';
  end if;
  select * into v_b from public.bookings where id = p_id for update;
  if not found or not (v_b.owner_id = v_uid or v_admin) then raise exception 'Booking not found' using errcode = 'P0002'; end if;
  if not v_admin and v_b.status <> 'completed' then
    raise exception 'Only paid bookings can be updated' using errcode = 'P0001';
  end if;
  if v_change and v_b.earned_at is not null and v_new is distinct from v_b.owner_status and not v_admin then
    raise exception 'Earnings were already recorded for this booking' using errcode = 'P0001';
  end if;

  if v_change and v_new = 'done' and v_b.earned_at is null and v_b.owner_id is not null and v_b.status = 'completed' then
    if coalesce(v_b.check_in, v_b.service_date) is null or coalesce(v_b.check_in, v_b.service_date) > (now() at time zone 'Africa/Cairo')::date then
      raise exception 'The service date has not passed yet' using errcode = 'P0001', detail = 'too_early';
    end if;
    -- the remaining balance of a deposit booking is collected ONLINE by the platform before the service: no execution / earnings until it is paid
    if v_b.pricing_model = 'legacy' and v_b.payment_plan = 'deposit' and v_b.remaining_amount > 0 and coalesce(v_b.data->>'balanceStatus', '') <> 'paid' and not v_admin then
      raise exception 'The remaining balance has not been paid yet' using errcode = 'P0001', detail = 'balance_due';
    end if;
    if v_b.pricing_model = 'v2' then
      -- commission and the owner's share were fixed when the booking was made: just recognise the earning
      update public.bookings
         set owner_status = 'done', owner_note = left(coalesce(p_note, owner_note), 1000), earned_at = now()
       where id = p_id returning * into v_b;
      return public.booking_to_json(v_b);
    end if;
    select commission_rate into v_rate from public.profiles where id = v_b.owner_id;
    if v_rate is null then
      select case v_b.kind when 'hotel' then commission_hotel when 'excursion' then commission_excursion
                           when 'transfer' then commission_transfer when 'package' then commission_package else default_commission_rate end
        into v_rate from public.platform_settings where id = 1;
    end if;
    v_comm := round(v_b.subtotal * v_rate, 2);
    update public.bookings
       set owner_status = 'done', owner_note = left(coalesce(p_note, owner_note), 1000), earned_at = now(),
           commission_rate = v_rate, commission_amount = v_comm, owner_amount = v_b.subtotal - v_comm
     where id = p_id returning * into v_b;
  else
    update public.bookings
       set owner_status = case when v_change then v_new else owner_status end, owner_note = left(coalesce(p_note, owner_note), 1000)
     where id = p_id returning * into v_b;
  end if;
  return public.booking_to_json(v_b);
end $$;

-- booking JSON: commission and the platform's cut are visible to the super admin ONLY. The booking's owner sees ownerShare
-- (what is theirs in total, what they collect on site, what the platform pays them); the guest sees neither.
create or replace function public.booking_to_json(b public.bookings)
returns jsonb language sql stable set search_path = '' as $$
  select b.data || jsonb_strip_nulls(jsonb_build_object(
    'id', b.id, 'type', b.kind, 'status', b.status, 'uid', b.user_id, 'ownerUid', b.owner_id,
    'total', b.total, 'subtotal', b.subtotal, 'taxes', b.taxes, 'gatewayFee', case when b.gateway_fee > 0 then b.gateway_fee end,
    'depositAmount', b.deposit_amount, 'remainingAmount', b.remaining_amount, 'amountDueNow', b.amount_due_now,
    'paymentPlan', b.payment_plan, 'currency', b.currency, 'nights', b.nights, 'pricingModel', b.pricing_model,
    'checkin', b.check_in, 'checkout', b.check_out, 'date', b.service_date,
    'reviewed', b.reviewed, 'ownerStatus', b.owner_status, 'ownerNote', b.owner_note, 'adminNote', b.admin_note,
    'needsRefund', case when b.needs_refund then true end,
    'cancelledAt', b.cancelled_at, 'cancelReason', b.cancel_reason, 'balanceDueAt', b.balance_due_at,
    'createdAt', b.created_at, 'expiresAt', b.expires_at,
    'ownerShare', case when b.pricing_model = 'v2' and b.commission_amount is not null and (b.owner_id = (select auth.uid()) or (select public.is_super_admin()))
        then jsonb_build_object('total', b.subtotal - b.commission_amount, 'onSite', b.remaining_amount, 'fromPlatform', b.owner_amount) end,
    'commission', case when (select public.is_super_admin()) and b.commission_amount is not null then b.commission_amount end,
    'commissionRate', case when (select public.is_super_admin()) and b.commission_rate is not null then round(b.commission_rate * 100, 2) end,
    'earning', case when b.earned_at is not null then
        case when (select public.is_super_admin()) then jsonb_build_object('gross', b.subtotal, 'rate', round(coalesce(b.commission_rate, 0) * 100, 2),
               'commission', b.commission_amount, 'net', b.owner_amount, 'void', b.earning_void, 'at', b.earned_at)
             else jsonb_build_object('net', b.owner_amount, 'void', b.earning_void, 'at', b.earned_at) end end
  ))
$$;

-- the platform's commission total is for the super admin only
create or replace function public.owner_balance(p_owner uuid default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  v_owner uuid := coalesce(p_owner, (select auth.uid()));
  v_earned numeric; v_comm numeric; v_adj numeric; v_paid numeric; v_open numeric;
begin
  if v_owner is distinct from (select auth.uid()) and not (select public.is_super_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select coalesce(sum(owner_amount), 0), coalesce(sum(commission_amount), 0) into v_earned, v_comm
    from public.bookings where owner_id = v_owner and earned_at is not null and not earning_void;
  select coalesce(sum(amount), 0) into v_adj from public.adjustments where owner_id = v_owner;
  select coalesce(sum(amount) filter (where status = 'paid'), 0), coalesce(sum(amount) filter (where status = 'requested'), 0)
    into v_paid, v_open from public.payouts where owner_id = v_owner;
  return jsonb_build_object('earned', v_earned, 'commission', case when (select public.is_super_admin()) then v_comm end, 'adjustments', v_adj,
                            'paid', v_paid, 'pending', v_open, 'available', v_earned + v_adj - v_paid - v_open);
end $$;

-- Kashier's fee: percent (e.g. 2.75), fixed EGP per transaction (3) and the VAT % charged on the fee only (14). Charged to the guest on top of
-- what is collected online. Changing it only affects NEW bookings.
create or replace function public.admin_set_gateway_fee(p_percent numeric, p_fixed numeric default 3, p_vat numeric default 14)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_percent is null or p_percent < 0 or p_percent > 15 or coalesce(p_fixed, 0) < 0 or coalesce(p_fixed, 0) > 100 or coalesce(p_vat, 0) < 0 or coalesce(p_vat, 0) > 50 then
    raise exception 'Invalid values' using errcode = '22023';
  end if;
  update public.platform_settings set gateway_fee_rate = round(p_percent / 100, 4), gateway_fixed_fee = coalesce(p_fixed, 0),
         gateway_fee_vat = round(coalesce(p_vat, 0) / 100, 4), updated_at = now() where id = 1;
  perform public.audit('settings', 'platform', '1', jsonb_build_object('gateway_fee_percent', p_percent, 'fixed', p_fixed, 'vat_percent', p_vat));
end $$;
grant execute on function public.admin_set_gateway_fee(numeric, numeric, numeric) to authenticated;


-- ==============================================================================================================
-- migration: 20261111000200_sellers.sql
-- ==============================================================================================================
-- Sellers (2026-11-11)
--  * A seller is a normal login with is_seller = true and a referral code. He gets his own dashboard (owner site -> /seller.html).
--  * When a booking is made from the seller's own account, or through his referral link (?ref=CODE), the seller earns a slice of the PLATFORM's
--    commission on that booking (default 2% of the pre-tax price, per-seller override in profiles.commission_rate, always capped at the
--    whole commission). Example: commission 5% -> platform 3% + seller 2%;  commission 10% -> platform 8% + seller 2%.
--    Nothing changes for the owner or the guest. The seller's earning is recognised (and voided on cancel / refund) together with the owner's.
--  * Sellers use the existing payout account / payout request / admin payout screens.
-- Run after 20261111000100_owner_collects_balance.sql.

alter table public.platform_settings
  add column if not exists seller_commission_rate numeric(5,4) not null default 0.02 check (seller_commission_rate >= 0 and seller_commission_rate <= 1);
alter table public.profiles
  add column if not exists is_seller   boolean not null default false,
  add column if not exists seller_code text check (seller_code is null or seller_code ~ '^[A-Z0-9]{4,12}$');
create unique index if not exists profiles_seller_code_key on public.profiles (seller_code) where seller_code is not null;
alter table public.bookings
  add column if not exists seller_id     uuid references public.profiles (id) on delete set null,
  add column if not exists seller_rate   numeric(5,4),
  add column if not exists seller_amount numeric(12,2) not null default 0 check (seller_amount >= 0);
create index if not exists bookings_seller_idx on public.bookings (seller_id) where seller_id is not null;

create or replace function public.is_seller()
returns boolean language sql stable security definer set search_path = '' as $$
  select coalesce((select p.is_seller and p.is_active from public.profiles p where p.id = (select auth.uid())), false)
$$;

create or replace function public.gen_seller_code() returns text language plpgsql volatile set search_path = '' as $$
declare c text;
begin
  loop
    c := upper(substr(md5(random()::text || clock_timestamp()::text), 1, 7));
    exit when not exists (select 1 from public.profiles where seller_code = c);
  end loop;
  return c;
end $$;

-- sellers may keep a payout account like owners do
drop policy if exists payout_accounts_insert on public.payout_accounts;
drop policy if exists payout_accounts_update on public.payout_accounts;
create policy payout_accounts_insert on public.payout_accounts for insert to authenticated
  with check (owner_id = (select auth.uid()) and ((select public.is_owner()) or (select public.is_seller())));
create policy payout_accounts_update on public.payout_accounts for update to authenticated
  using (owner_id = (select auth.uid()) and ((select public.is_owner()) or (select public.is_seller())))
  with check (owner_id = (select auth.uid()) and ((select public.is_owner()) or (select public.is_seller())));

-- the seller's own bookings: only what he needs (no guest contact details, no owner / commission figures)
create or replace function public.seller_bookings(p_seller uuid default null, p_limit integer default 500)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_s uuid := coalesce(p_seller, (select auth.uid()));
begin
  if v_s is distinct from (select auth.uid()) and not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', b.id, 'type', b.kind, 'status', b.status, 'createdAt', b.created_at, 'serviceDate', coalesce(b.check_in, b.service_date),
      'customer', split_part(coalesce(b.guest_name, ''), ' ', 1),
      'item', coalesce(b.data->'hotelName'->>'en', b.data->'hotelName'->>'ar', b.data->>'hotelName', b.data->'title'->>'en', b.data->'title'->>'ar', b.data->>'title', b.data->>'vehicleType', ''),
      'subtotal', b.subtotal, 'rate', round(coalesce(b.seller_rate, 0) * 100, 2), 'amount', b.seller_amount, 'currency', b.currency,
      'earnedAt', b.earned_at, 'void', b.earning_void, 'viaOwnAccount', b.user_id = v_s) order by b.created_at desc)
    from (select * from public.bookings where seller_id = v_s and status <> 'pending_payment' and status <> 'failed'
           order by created_at desc limit least(greatest(p_limit, 1), 2000)) b
  ), '[]'::jsonb);
end $$;
grant execute on function public.seller_bookings(uuid, integer) to authenticated;

-- the platform-wide default seller share (percent), set by the super admin
create or replace function public.admin_set_seller_rate(p_percent numeric)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_percent is null or p_percent < 0 or p_percent > 100 then raise exception 'Invalid values' using errcode = '22023'; end if;
  update public.platform_settings set seller_commission_rate = round(p_percent / 100, 4), updated_at = now() where id = 1;
  perform public.audit('settings', 'platform', '1', jsonb_build_object('seller_percent', p_percent));
end $$;
grant execute on function public.admin_set_seller_rate(numeric) to authenticated;

create or replace function public.admin_remove_seller(p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.profiles set is_seller = false where id = p_user;      -- the code and old earnings stay on record
  perform public.audit('seller_removed', 'profile', p_user::text, '{}'::jsonb);
end $$;
grant execute on function public.admin_remove_seller(uuid) to authenticated;

create or replace function public.create_booking(p jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  v_uid     uuid := (select auth.uid());
  v_type    text := p->>'type';
  v_item_id text;
  v_prop    public.properties;
  v_price   jsonb;
  v_prof    public.profiles;
  v_plan    text;
  v_data    jsonb;
  v_row     public.bookings;
  v_rate    numeric;
  v_comm    numeric;
  v_seller  uuid;
  v_srate   numeric;
  v_samt    numeric := 0;
begin
  if v_uid is null then raise exception 'Not authenticated' using errcode = '28000'; end if;
  if jsonb_typeof(p) <> 'object' then raise exception 'booking object required' using errcode = '22023'; end if;
  if coalesce(p->>'id', '') !~ '^[A-Za-z0-9_-]{3,64}$' then raise exception 'Invalid booking id' using errcode = '22023'; end if;
  if v_type not in ('hotel', 'excursion', 'transfer', 'package') then raise exception 'Unknown booking type' using errcode = '22023'; end if;
  if coalesce(p->>'currency', '') <> 'EGP' then raise exception 'Only EGP is supported' using errcode = '22023'; end if;

  v_item_id := p->>(case v_type when 'hotel' then 'hotelId' when 'excursion' then 'excursionId' when 'package' then 'packageId' else 'transferId' end);
  if v_item_id is null or v_item_id = '' then raise exception 'Missing item id' using errcode = '22023'; end if;

  select * into v_prop from public.properties
   where id = v_item_id and kind = v_type::public.property_kind and status = 'published';
  if not found then raise exception 'Item not found' using errcode = 'P0002'; end if;

  v_price := public.compute_booking_price(p, v_prop.data);
  if coalesce(p->>'total', '') !~ '^[0-9]+(\.[0-9]+)?$' or (p->>'total')::numeric <> (v_price->>'total')::numeric then
    raise exception 'price_changed' using errcode = 'P0001', detail = 'price_changed', hint = v_price->>'total';
  end if;

  if exists (select 1 from public.bookings where id = p->>'id') then
    raise exception 'Booking id already exists' using errcode = '23505';
  end if;

  v_plan := case when p->>'paymentPlan' = 'deposit' then 'deposit' else 'full' end;
  select * into v_prof from public.profiles where id = v_uid;

  -- the platform's commission is fixed NOW on the full pre-tax price; it comes out of what we collect, never off the on-site part
  select commission_rate into v_rate from public.profiles where id = v_prop.owner_id;
  if v_rate is null then
    select case v_type when 'hotel' then commission_hotel when 'excursion' then commission_excursion
                       when 'transfer' then commission_transfer when 'package' then commission_package else default_commission_rate end
      into v_rate from public.platform_settings where id = 1;
  end if;
  v_comm := round((v_price->>'subtotal')::numeric * coalesce(v_rate, 0), 2);

  -- Seller share: if the booking is made from a seller's own account, or through a seller's referral code, the seller gets a slice of the
  -- platform's commission (never more than the whole commission). It does not change what the owner or the guest pay or receive.
  select id into v_seller from public.profiles where id = v_uid and is_seller and is_active;
  if v_seller is null and nullif(btrim(coalesce(p->>'ref', '')), '') is not null then
    select id into v_seller from public.profiles where is_seller and is_active and id <> v_uid and upper(seller_code) = upper(btrim(p->>'ref'));
  end if;
  if v_seller is not null and lower(btrim(coalesce(p->>'email', ''))) = (select lower(coalesce(email, '')) from public.profiles where id = v_seller) then
    v_seller := null;                                   -- no commission on a seller's own booking
  end if;
  if v_seller is not null then
    select coalesce(pr.commission_rate, st.seller_commission_rate) into v_srate from public.profiles pr, public.platform_settings st where pr.id = v_seller and st.id = 1;
    v_srate := least(coalesce(v_srate, 0), coalesce(v_rate, 0));
    v_samt  := round((v_price->>'subtotal')::numeric * v_srate, 2);
  end if;

  -- everything the client sent, minus server-owned fields and anything that looks like card data
  v_data := (p - array['ownerUid','ownerStatus','ownerNote','adminNote','needsRefund','cancelledBy','cancelReason','ref','cancelledAt',
                       'uid','status','createdAt','expiresAt','card','cardNumber','cvv','cvc','expiry'])
            || jsonb_build_object('paymentPlan', v_plan);
  if jsonb_typeof(v_data->'payment') = 'object' then v_data := v_data - 'payment'; end if;

  insert into public.bookings (
    id, user_id, property_id, owner_id, kind, status, payment_plan, currency,
    subtotal, taxes, gateway_fee, total, deposit_amount, remaining_amount, amount_due_now,
    pricing_model, commission_rate, commission_amount, owner_amount, seller_id, seller_rate, seller_amount,
    check_in, check_out, service_date, nights,
    guest_name, guest_email, guest_phone, data, expires_at
  ) values (
    p->>'id', v_uid, v_prop.id, v_prop.owner_id, v_type::public.property_kind, 'pending_payment', v_plan, 'EGP',
    (v_price->>'subtotal')::numeric, (v_price->>'taxes')::numeric, (v_price->>'fee')::numeric, (v_price->>'total')::numeric,
    (v_price->>'deposit')::numeric, (v_price->>'remaining')::numeric, (v_price->>'due')::numeric,
    'v2', v_rate, v_comm, (v_price->>'collected')::numeric - v_comm, v_seller, case when v_seller is not null then v_srate end, v_samt,
    case when v_type = 'hotel' then (p->>'checkin')::date end,
    case when v_type = 'hotel' then (p->>'checkout')::date end,
    case when v_type <> 'hotel' then (p->>'date')::date end,
    nullif(v_price->>'nights', '')::integer,
    left(coalesce(nullif(p->>'name', ''), v_prof.display_name), 120),
    left(coalesce(nullif(p->>'email', ''), v_prof.email), 254),
    left(coalesce(nullif(p->>'phone', ''), v_prof.phone), 30),
    v_data,
    now() + interval '2 hours'
  ) returning * into v_row;

  return jsonb_build_object('success', true, 'booking', public.booking_to_json(v_row));
end $$;

create or replace function public.booking_to_json(b public.bookings)
returns jsonb language sql stable set search_path = '' as $$
  select b.data || jsonb_strip_nulls(jsonb_build_object(
    'id', b.id, 'type', b.kind, 'status', b.status, 'uid', b.user_id, 'ownerUid', b.owner_id,
    'total', b.total, 'subtotal', b.subtotal, 'taxes', b.taxes, 'gatewayFee', case when b.gateway_fee > 0 then b.gateway_fee end,
    'depositAmount', b.deposit_amount, 'remainingAmount', b.remaining_amount, 'amountDueNow', b.amount_due_now,
    'paymentPlan', b.payment_plan, 'currency', b.currency, 'nights', b.nights, 'pricingModel', b.pricing_model,
    'checkin', b.check_in, 'checkout', b.check_out, 'date', b.service_date,
    'reviewed', b.reviewed, 'ownerStatus', b.owner_status, 'ownerNote', b.owner_note, 'adminNote', b.admin_note,
    'needsRefund', case when b.needs_refund then true end,
    'cancelledAt', b.cancelled_at, 'cancelReason', b.cancel_reason, 'balanceDueAt', b.balance_due_at,
    'createdAt', b.created_at, 'expiresAt', b.expires_at,
    'ownerShare', case when b.pricing_model = 'v2' and b.commission_amount is not null and (b.owner_id = (select auth.uid()) or (select public.is_super_admin()))
        then jsonb_build_object('total', b.subtotal - b.commission_amount, 'onSite', b.remaining_amount, 'fromPlatform', b.owner_amount) end,
    'commission', case when (select public.is_super_admin()) and b.commission_amount is not null then b.commission_amount end,
    'sellerAmount', case when (select public.is_super_admin()) and b.seller_id is not null then b.seller_amount end,
    'sellerName', case when (select public.is_super_admin()) and b.seller_id is not null then (select coalesce(display_name, email) from public.profiles where id = b.seller_id) end,
    'platformNet', case when (select public.is_super_admin()) and b.commission_amount is not null then b.commission_amount - b.seller_amount end,
    'commissionRate', case when (select public.is_super_admin()) and b.commission_rate is not null then round(b.commission_rate * 100, 2) end,
    'earning', case when b.earned_at is not null then
        case when (select public.is_super_admin()) then jsonb_build_object('gross', b.subtotal, 'rate', round(coalesce(b.commission_rate, 0) * 100, 2),
               'commission', b.commission_amount, 'net', b.owner_amount, 'void', b.earning_void, 'at', b.earned_at)
             else jsonb_build_object('net', b.owner_amount, 'void', b.earning_void, 'at', b.earned_at) end end
  ))
$$;

create or replace function public.owner_balance(p_owner uuid default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  v_owner uuid := coalesce(p_owner, (select auth.uid()));
  v_earned numeric; v_sell numeric; v_comm numeric; v_adj numeric; v_paid numeric; v_open numeric;
begin
  if v_owner is distinct from (select auth.uid()) and not (select public.is_super_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select coalesce(sum(owner_amount), 0), coalesce(sum(commission_amount), 0) into v_earned, v_comm
    from public.bookings where owner_id = v_owner and earned_at is not null and not earning_void;
  select coalesce(sum(seller_amount), 0) into v_sell                      -- a seller's share of the commission, recognised together with the owner's earning
    from public.bookings where seller_id = v_owner and earned_at is not null and not earning_void;
  v_earned := v_earned + v_sell;
  select coalesce(sum(amount), 0) into v_adj from public.adjustments where owner_id = v_owner;
  select coalesce(sum(amount) filter (where status = 'paid'), 0), coalesce(sum(amount) filter (where status = 'requested'), 0)
    into v_paid, v_open from public.payouts where owner_id = v_owner;
  return jsonb_build_object('earned', v_earned, 'commission', case when (select public.is_super_admin()) then v_comm end, 'sellerEarned', v_sell, 'adjustments', v_adj,
                            'paid', v_paid, 'pending', v_open, 'available', v_earned + v_adj - v_paid - v_open);
end $$;

create or replace function public.request_payout(p_amount numeric)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  v_uid uuid := (select auth.uid());
  v_acc public.payout_accounts;
  v_min numeric;
  v_bal jsonb;
  v_id  uuid;
begin
  if not ((select public.is_owner()) or (select public.is_seller())) then raise exception 'forbidden' using errcode = '42501'; end if;
  perform 1 from public.profiles where id = v_uid for update;             -- serialise concurrent requests
  select * into v_acc from public.payout_accounts where owner_id = v_uid;
  if not found then raise exception 'Add a payout account first' using errcode = 'P0001'; end if;
  if v_acc.locked_until is not null and v_acc.locked_until > now() then
    raise exception 'Payouts are paused after a payout account change' using errcode = 'P0001', detail = 'account_locked';
  end if;
  if exists (select 1 from public.payouts where owner_id = v_uid and status = 'requested') then
    raise exception 'You already have an open payout request' using errcode = 'P0001';
  end if;
  select min_payout into v_min from public.platform_settings where id = 1;
  if p_amount is null or p_amount < v_min then raise exception 'Minimum payout is %', v_min using errcode = '22023'; end if;
  v_bal := public.owner_balance(v_uid);
  if p_amount > (v_bal->>'available')::numeric then raise exception 'Amount exceeds available balance' using errcode = '22023'; end if;
  insert into public.payouts (owner_id, amount, method, account)
  values (v_uid, p_amount, v_acc.method, v_acc.details) returning id into v_id;
  return v_id;
end $$;

create or replace function public.admin_owner_balances()
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'uid', p.id, 'earned', coalesce(e.earned, 0), 'commission', coalesce(e.comm, 0), 'adjustments', coalesce(a.adj, 0),
      'paid', coalesce(y.paid, 0), 'pending', coalesce(y.open, 0),
      'available', coalesce(e.earned, 0) + coalesce(a.adj, 0) - coalesce(y.paid, 0) - coalesce(y.open, 0)))
    from public.profiles p
    left join (select u.uid, sum(u.earned) earned, sum(u.comm) comm from (
                 select owner_id uid, owner_amount earned, commission_amount comm from public.bookings where earned_at is not null and not earning_void and owner_id is not null
                 union all
                 select seller_id, seller_amount, 0 from public.bookings where earned_at is not null and not earning_void and seller_id is not null) u
               group by u.uid) e on e.uid = p.id
    left join (select owner_id, sum(amount) adj from public.adjustments group by owner_id) a on a.owner_id = p.id
    left join (select owner_id, sum(amount) filter (where status = 'paid') paid, sum(amount) filter (where status = 'requested') open
                 from public.payouts group by owner_id) y on y.owner_id = p.id
    where p.role = 'owner' or p.is_seller
  ), '[]'::jsonb);
end $$;

create or replace function public.admin_update_owner(
  p_user uuid, p_name text default null, p_phone text default null, p_role text default null,
  p_commission numeric default null, p_set_commission boolean default false)
returns void language plpgsql security definer set search_path = '' as $$
declare
  v_seller boolean := (p_role = 'seller');
  v_kinds public.property_kind[] := case when p_role = 'seller' then '{}'::public.property_kind[] else public.console_role_kinds(p_role) end;
begin
  if not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_role is not null and p_role <> '' and v_kinds is null then raise exception 'Unknown role' using errcode = '22023'; end if;
  if p_set_commission and p_commission is not null and (p_commission < 0 or p_commission > 100) then
    raise exception 'Invalid commission' using errcode = '22023';
  end if;
  update public.profiles
     set display_name = coalesce(nullif(left(btrim(p_name), 120), ''), display_name),
         phone = coalesce(nullif(left(btrim(p_phone), 30), ''), phone),
         role = case when v_seller then 'user'::public.user_role when v_kinds is not null then 'owner'::public.user_role else role end,
         owner_kinds = coalesce(v_kinds, owner_kinds),
         is_seller = case when p_role is null or p_role = '' then is_seller else v_seller end,
         seller_code = case when v_seller and seller_code is null then public.gen_seller_code() else seller_code end,
         commission_rate = case when p_set_commission then p_commission / 100 else commission_rate end
   where id = p_user and role <> 'super_admin';
  if not found then raise exception 'User not found' using errcode = 'P0002'; end if;
  perform public.audit('owner_updated', 'profile', p_user::text, jsonb_build_object('role', p_role, 'commission', p_commission));
end $$;


-- ==============================================================================================================
-- migration: 20261112000100_seller_desk.sql
-- ==============================================================================================================
-- 2026-11-12 — Seller desk: the seller books for a walk-in customer from his own dashboard, pays the platform with his e-wallet
-- (Kashier wallet, same worker endpoints as the site) and the customer receives the voucher by e-mail / WhatsApp.
--
--  * seller_quote(p)      – the exact price the server will charge (same compute_booking_price create_booking checks). Sellers only.
--  * public_voucher(id)   – a seller booking's voucher for the CUSTOMER, who has no account. The booking id is the secret: sellers' ids are
--                           generated by the dashboard with >= 22 random characters, and only confirmed seller bookings are served here.
--
-- create_booking already attributes a booking made from a seller's own account to him (commission), unless the guest e-mail is his own.

create or replace function public.seller_quote(p jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  v_type text := p->>'type';
  v_id   text;
  v_prop public.properties;
begin
  if not (select public.is_seller()) then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(p) <> 'object' or v_type not in ('hotel', 'excursion', 'transfer', 'package') then raise exception 'Unknown booking type' using errcode = '22023'; end if;
  v_id := p->>(case v_type when 'hotel' then 'hotelId' when 'excursion' then 'excursionId' when 'package' then 'packageId' else 'transferId' end);
  select * into v_prop from public.properties where id = v_id and kind = v_type::public.property_kind and status = 'published';
  if not found then raise exception 'Item not found' using errcode = 'P0002'; end if;
  return public.compute_booking_price(p, v_prop.data);
end $$;
revoke all on function public.seller_quote(jsonb) from public, anon;
grant execute on function public.seller_quote(jsonb) to authenticated;

create or replace function public.public_voucher(p_id text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_row public.bookings;
begin
  if coalesce(p_id, '') !~ '^[A-Za-z0-9_-]{20,64}$' then return null; end if;
  select * into v_row from public.bookings where id = p_id and seller_id is not null and status = 'completed';
  if not found then return null; end if;
  return public.booking_to_json(v_row) - array['uid', 'ownerUid', 'ownerStatus', 'ownerNote', 'adminNote', 'ownerShare', 'earning', 'commission',
                                              'sellerAmount', 'sellerName', 'platformNet', 'commissionRate', 'payment'];
end $$;
revoke all on function public.public_voucher(text) from public;
grant execute on function public.public_voucher(text) to anon, authenticated;

-- the seller sees contact details only of bookings he made himself from his dashboard (he typed them in): needed to resend the voucher
create or replace function public.seller_bookings(p_seller uuid default null, p_limit integer default 500)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_s uuid := coalesce(p_seller, (select auth.uid()));
begin
  if v_s is distinct from (select auth.uid()) and not (select public.is_super_admin()) then raise exception 'forbidden' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', b.id, 'type', b.kind, 'status', b.status, 'createdAt', b.created_at, 'serviceDate', coalesce(b.check_in, b.service_date),
      'customer', case when b.user_id = v_s then coalesce(b.guest_name, '') else split_part(coalesce(b.guest_name, ''), ' ', 1) end,
      'phone', case when b.user_id = v_s then b.guest_phone end, 'email', case when b.user_id = v_s then b.guest_email end,
      'plan', b.payment_plan, 'paidNow', b.amount_due_now, 'onSite', b.remaining_amount,
      'item', coalesce(b.data->'hotelName'->>'en', b.data->'hotelName'->>'ar', b.data->>'hotelName', b.data->'title'->>'en', b.data->'title'->>'ar', b.data->>'title', b.data->>'vehicleType', ''),
      'subtotal', b.subtotal, 'rate', round(coalesce(b.seller_rate, 0) * 100, 2), 'amount', b.seller_amount, 'currency', b.currency,
      'earnedAt', b.earned_at, 'void', b.earning_void, 'viaOwnAccount', b.user_id = v_s) order by b.created_at desc)
    from (select * from public.bookings where seller_id = v_s and status <> 'pending_payment' and status <> 'failed'
           order by created_at desc limit least(greatest(p_limit, 1), 2000)) b
  ), '[]'::jsonb);
end $$;
grant execute on function public.seller_bookings(uuid, integer) to authenticated;

